<?php
function authStart(string $title,string $subtitle,string $error='',string $step='YOUR EVERYDAY, MADE EASIER'): void { ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($title)?> · CarinderEase</title><link rel="stylesheet" href="assets/app.css"><link rel="stylesheet" href="assets/auth.css"><script src="assets/auth.js" defer></script></head><body class="ce-auth"><main class="welcome-shell"><section class="welcome-art" aria-label="Illustrated Filipino dishes"><a class="welcome-brand" href="login.php"><span class="welcome-mark">C</span>CarinderEase <small>✦</small></a><div class="art-copy"><span class="welcome-kicker">A LITTLE LESS HASSLE. A LOT MORE HEART.</span><h1>Good food.<br>Great days.<br><em>Your carinderia.</em></h1><p>From your first pot of rice to your last sale.<br>Make room for what you love.</p></div><div class="food-scene"><span class="scene-orbit"></span><div class="dish main-dish"><img src="assets/food/adobo.svg" alt="Pork adobo illustration"></div><div class="dish side-dish"><img src="assets/food/rice.svg" alt="Steamed rice"></div><div class="dish veg-dish"><img src="assets/food/vegetables.svg" alt="Vegetable dish"></div><span class="floating-note">✦ Less paperwork.<br><strong>More lutong bahay.</strong></span></div><div class="art-bottom"><span>01 / PREPARE</span><span>02 / SERVE</span><span>03 / GROW</span></div></section><section class="welcome-form"><a class="mobile-brand" href="login.php">✦ CarinderEase</a><div class="form-inner"><div class="welcome-kicker green"><?=h($step)?></div><h2><?=h($title)?></h2><p class="form-subtitle"><?=h($subtitle)?></p><?php if(isset($_SESSION['flash'])){echo '<div class="notice" role="status">'.h($_SESSION['flash']['text']).'</div>';unset($_SESSION['flash']);}if($error)echo '<div class="notice error" role="alert">'.h($error).'</div>'; }
function authEnd(): void {echo '</div><footer class="welcome-footer">© '.date('Y').' CarinderEase <span>Family business edition</span></footer></section></main></body></html>';}
function authForm(): void {echo '<form method="post" class="auth-form"><input type="hidden" name="csrf" value="'.h(csrf()).'">';}
function authField(string $label,string $name,string $type='text',string $extra='',string $value=''): void {static $seq=0;$id='auth-'.$name.'-'.++$seq;echo '<div class="auth-field"><label for="'.h($id).'">'.h($label).'</label><div class="input-wrap"><input id="'.h($id).'" name="'.h($name).'" type="'.h($type).'" value="'.h($value).'" required '.$extra.'>';if($type==='password')echo '<button type="button" class="password-toggle" aria-label="Show '.h(strtolower($label)).'" aria-controls="'.h($id).'" aria-pressed="false"><svg viewBox="0 0 24 24" width="21" height="21" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg></button>';echo '</div></div>';}
function authSubmit(string $label): void {echo '<button class="auth-submit" data-loading="Please wait…">'.h($label).'<span aria-hidden="true">↗</span></button></form>';}
